-- PT114-S2-Q13. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT114-S2-Q13$batch04$ AND q.stimulus=$batch04$Historian: Political regimes that routinely censor various forms of expression on the grounds that they undermine public morality inevitably attempt to expand the categories of proscribed expression to include criticisms that these regimes perceive to threaten their power. Accordingly, many totalitarian regimes classify as blasphemous or pornographic those writings that would, if widely influential, reduce public passivity.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption on which the historian's reasoning depends?$batch04$ AND q.correct_choice=$batch04$C$batch04$) THEN RAISE EXCEPTION 'Question changed: PT114-S2-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT114-S2-Q13$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S2-Q13'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT114-S2-Q13$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Many totalitarian regimes label as blasphemous or pornographic the writings that would reduce public passivity if they became influential.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Regimes that censor in the name of public morality always try to widen censorship to cover criticism they *perceive* as a threat to their power.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The evidence covers criticism the regime sees as a threat. The conclusion is about writings that would reduce passivity. To connect them, the regime has to see a loss of passivity as a threat.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A link: a totalitarian regime can see a loss of public passivity as a threat to its power.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT114-S2-Q13$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Popularity is never part of the argument.$batch04$), ($batch04$B$batch04$, $batch04$The argument does not need some censoring regimes to be non-totalitarian.$batch04$), ($batch04$C$batch04$, $batch04$Negate it: a totalitarian regime *cannot* see a loss of passivity as a threat. Then the evidence gives it no reason to censor these writings, and the conclusion falls apart.$batch04$), ($batch04$D$batch04$, $batch04$The argument depends on what regimes *perceive*. It does not need passivity to actually be necessary for keeping power.$batch04$), ($batch04$E$batch04$, $batch04$The conclusion says many regimes censor these writings. It does not need most of the labeled writings to be of this kind.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT114-S2-Q13$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
